// ==========================================================================
// 🛡️ POLYFILL DE SEGURIDAD MÓVIL (SAFE STORAGE Y MANEJO DE ERRORES EN MÓVILES)
// ==========================================================================
window.safeStorage = {
    _mem: {},
    getItem: function(key) {
        try {
            if (window.localStorage) {
                return window.localStorage.getItem(key);
            }
        } catch(e) {}
        return this._mem[key] || null;
    },
    setItem: function(key, val) {
        try {
            if (window.localStorage) {
                window.localStorage.setItem(key, val);
            }
        } catch(e) {}
        this._mem[key] = val;
    },
    removeItem: function(key) {
        try {
            if (window.localStorage) {
                window.localStorage.removeItem(key);
            }
        } catch(e) {}
        delete this._mem[key];
    }
};

// Capturador de errores global para evitar que la pantalla se quede congelada en móviles
window.addEventListener('error', function(e) {
    console.warn("Mobile Error Intercepted:", e.message);
    const loadingElem = document.querySelector('.loading-spinner');
    if (loadingElem && typeof renderApp === 'function') {
        try { renderApp(); } catch(err) {}
    }
});



// ==========================================================================
// F01, F10, F11: SEGURIDAD CRIPTOGRÁFICA (SHA-256), AUTENTICACIÓN Y FOLIOS
// ==========================================================================
const AUTH_SALT = 'CSB-2627-AUTH-SALT:';

async function hashPassword(pwd) {
    if (!pwd) return '';
    try {
        const encoder = new TextEncoder();
        const data = encoder.encode(AUTH_SALT + pwd.trim());
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    } catch(e) {
        let hash = 0;
        const str = AUTH_SALT + pwd.trim();
        for (let i = 0; i < str.length; i++) {
            hash = ((hash << 5) - hash) + str.charCodeAt(i);
            hash |= 0;
        }
        return 'FALLBACK-' + Math.abs(hash).toString(16);
    }
}

async function computeDocumentSHA256(canonicalData) {
    try {
        const canonicalString = typeof canonicalData === 'string' ? canonicalData : JSON.stringify(canonicalData);
        const encoder = new TextEncoder();
        const data = encoder.encode(canonicalString);
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    } catch(e) {
        return 'SHA256-' + Date.now();
    }
}

function slugify(text) {
    if (!text) return 'DOC';
    return text.toString().toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .toUpperCase();
}

function generateUniqueFolio(teacherName) {
    const t = TEACHERS.find(x => x.name === teacherName);
    const tid = t ? t.id.toUpperCase() : 'DOC';
    const nameSlug = slugify(teacherName);
    return `ACTA-2627-${tid}-${nameSlug}`;
}


// Helper para limpiar títulos duplicados de bloques (ej. Bloque 1: BLOQUE 1:)
function cleanBlockTitle(title, blockId) {
    if (!title) return '';
    let clean = title.replace(/^bloque\s*\d+\s*:\s*/i, '').trim();
    clean = clean.replace(/^bloque\s*\d+\s*/i, '').trim();
    if (blockId) {
        const num = blockId.replace('b', '');
        return `Bloque ${num}: ${clean}`;
    }
    return clean;
}

