// 8. AUTENTICACIÓN
async function handleLogin(username, password) {
    try {
        if (!username || !password || !username.trim() || !password.trim()) {
            showToast('Por favor, rellene todos los campos.');
            return;
        }

        const inputUser = username.trim().toLowerCase();
        const cleanInputUser = inputUser.replace(/\s+/g, '');
        const hashedInputPwd = await hashPassword(password);

        // Match teacher by exact ID, exact Name, or clean name (ignoring spaces and accents)
        const normalizeStr = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '');
        const normInput = normalizeStr(username);

        const matchedTeacher = TEACHERS.find(t => {
            const tId = (t.id || '').toLowerCase();
            const tName = (t.name || '').toLowerCase();
            const tClean = tName.replace(/\s+/g, '');
            const tNorm = normalizeStr(t.name);
            const tAlias = t.alias ? (t.alias || '').toLowerCase() : '';
            const tAliasNorm = t.alias ? normalizeStr(t.alias) : '';
            return tId === inputUser || tName === inputUser || tClean === cleanInputUser || tNorm === normInput || tId === normInput || (tAlias && (tAlias === inputUser || tAliasNorm === normInput));
        });

        if (matchedTeacher) {
            // Aceptar 1234 o demo123 para perfiles demo, o contraseña por hash o texto plano (insensible a mayúsculas)
            const pwdClean = password.trim();
            const isDemoAccount = matchedTeacher.id.startsWith('demo-');
            const isDemoMatch = isDemoAccount && (pwdClean === '1234' || pwdClean === 'demo123' || pwdClean === 'demo' || pwdClean.toLowerCase() === 'demo');
            const isPlainMatch = matchedTeacher.password && (pwdClean.toLowerCase() === matchedTeacher.password.toLowerCase());
            const isHashMatch = hashedInputPwd === matchedTeacher.authHash;
            
            if (isHashMatch || isPlainMatch || isDemoMatch) {
                state.currentUser = {
                    id: matchedTeacher.id,
                    name: matchedTeacher.name,
                    role: matchedTeacher.role,
                    subrole: matchedTeacher.subrole,
                    etapa: matchedTeacher.etapa,
                    cargo: matchedTeacher.cargo
                };
                state.currentBlockIndex = 0;
                state.showingSuccessScreen = false;
                safeStorage.setItem('session', JSON.stringify(state.currentUser));
                
                // Asegurar inicialización de la evaluación en la base de datos
                if (db && typeof db.getUserData === 'function') {
                    db.getUserData(matchedTeacher.name);
                }
                
                if (db && typeof db.logEvent === 'function') {
                    db.logEvent(matchedTeacher.name, 'ACCESO_SISTEMA', { rol: matchedTeacher.role, etapa: matchedTeacher.etapa });
                }
                renderApp();
                showToast(`Bienvenido/a, ${matchedTeacher.name}`);
                return;
            } else {
                showToast('Contraseña incorrecta. Por favor, verifique su clave.');
                return;
            }
        }

        showToast('Usuario no encontrado. Seleccione su nombre de la lista de acceso rápido.');
    } catch (err) {
        console.error('Login Error:', err);
        showToast('Error al iniciar sesión: ' + (err.message || 'Error inesperado'));
    }
}

function handleLogout() {
    if (state.currentUser && db && typeof db.logEvent === 'function') {
        db.logEvent(state.currentUser.name, 'CIERRE_SESION', { rol: state.currentUser.role });
    }
    state.currentUser = null;
    state.currentBlockIndex = 0;
    state.selectedTeacherForDetail = null;
    state.interviewModeActive = false;
    state.showingSuccessScreen = false; // F18: Reset success screen on logout
    safeStorage.removeItem('session');
    
    Object.values(state.chartInstances).forEach(chart => chart.destroy());
    state.chartInstances = {};
    
    renderApp();
    showToast('Sesión cerrada correctamente');
}
window.handleLogout = handleLogout;
window.handleLogoClick = function() {
    if (state.currentUser) {
        if (state.currentUser.role === 'director') {
            state.activeDirectorTab = 'summary';
            state.selectedTeacherForDetail = null;
            renderDirectorView();
        } else {
            renderTeacherView();
        }
    } else {
        renderApp();
    }
};

// 9. ROUTER PRINCIPAL (SPLIT-SCREEN LOGIN ADAPTADO)
function renderApp() {
    const session = safeStorage.getItem('session');
    if (session) {
        try {
            state.currentUser = JSON.parse(session);
        } catch(e) {
            state.currentUser = null;
        }
    }

    // Actualizar visibilidad de botón cerrar sesión en la cabecera general
    const headerLogout = document.getElementById('header-logout-btn');
    if (headerLogout) {
        headerLogout.style.display = state.currentUser ? 'inline-flex' : 'none';
    }

    document.body.classList.toggle('is-login', !state.currentUser);

    if (!state.currentUser) {
        renderLoginView();
    } else if (state.currentUser.role === 'teacher') {
        renderTeacherView();
    } else if (state.currentUser.role === 'director') {
        renderDirectorView();
    }
}

